<?php
namespace App\Modules\Orders\Application;
use App\Models\User;use App\Modules\Audit\Application\RecordAuditEvent;use App\Modules\Inventory\Domain\Models\InventoryBalance;use App\Modules\Orders\Domain\Enums\ReservationStatus;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\SalesOrder;use DomainException;use Illuminate\Support\Facades\DB;
class ConfirmSalesOrder {public function __construct(private readonly RebuildOrderDemand $demand,private readonly RecordAuditEvent $audit){}public function execute(SalesOrder $order,User $actor):SalesOrder{return DB::transaction(function()use($order,$actor){$order=SalesOrder::query()->with('lines.presentation')->lockForUpdate()->findOrFail($order->id);if($order->status!==SalesOrderStatus::Draft)throw new DomainException('Solo se confirma un pedido en borrador.');$complete=true;foreach($order->lines as $line){$balance=InventoryBalance::query()->firstOrCreate(['presentation_id'=>$line->presentation_id],['physical_quantity'=>0,'reserved_quantity'=>0,'average_unit_cost'=>0]);$balance=InventoryBalance::query()->where('id',$balance->id)->lockForUpdate()->sole();$available=max(0,(float)$balance->availableQuantity());$reserved=(string)min($available,(float)$line->ordered_quantity);if(bccomp($reserved,'0',6)>0){$line->reservations()->create(['presentation_id'=>$line->presentation_id,'quantity'=>$reserved,'status'=>ReservationStatus::Active,'reserved_at'=>now()]);$balance->update(['reserved_quantity'=>bcadd($balance->reserved_quantity,$reserved,6)]);}$line->update(['reserved_quantity'=>$reserved]);if(bccomp($reserved,$line->ordered_quantity,6)<0)$complete=false;}$this->demand->execute($order);$status=$complete?SalesOrderStatus::Ready:SalesOrderStatus::PendingProduction;$order->update(['status'=>$status]);$order->histories()->create(['from_status'=>SalesOrderStatus::Draft->value,'to_status'=>$status->value,'changed_by'=>$actor->id,'changed_at'=>now(),'notes'=>'Pedido confirmado y reserva calculada.']);$this->audit->execute('orders.confirmed',$order,$actor,after:$order->fresh(['lines','lines.reservations'])->toArray());return $order->fresh(['lines','lines.reservations']);});}}
